"<a href=\"https://community.monzo.com/t/vote-for-monzo-in-the-british-bank-awards-2024/158682\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"fx-aw-year\">2024</span><b class=\"fx-aw-tag\">Highly commended</b><span class=\"fx-aw-name\">Best Credit Card Provider</span><span class=\"fx-aw-org\">British Bank Awards ↗</span></a>": "<a href=\"https://community.monzo.com/t/vote-for-monzo-in-the-british-bank-awards-2024/158682\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"fx-aw-year\">2024</span><b class=\"fx-aw-tag\">Mención especial</b><span class=\"fx-aw-name\">Mejor proveedor de tarjetas de crédito</span><span class=\"fx-aw-org\">British Bank Awards ↗</span></a>",
